const fs = require('fs');

// ─── MATEMÁTICAS ─────────────────────────────────────────────────────────────
{
  const path = 'rag_api/knowledge_base/matematicas.json';
  const data = JSON.parse(fs.readFileSync(path, 'utf8'));
  const nuevas = [
    // GRADO 3
    {id:'mat_g3_073',grado:3,tema:'polígonos',pregunta:'¿Qué es un polígono y cuáles hay?',respuesta:'Un polígono es una figura plana cerrada formada por líneas rectas llamadas lados. Según el número de lados: triángulo (3 lados), cuadrado o rectángulo (4 lados), pentágono (5 lados), hexágono (6 lados). Los reconoces en la vida diaria en señales de tráfico, ventanas y baldosas.',palabras_clave:['polígono','triángulo','cuadrado','rectángulo','pentágono','hexágono','lados','figura plana']},
    {id:'mat_g3_074',grado:3,tema:'números pares e impares',pregunta:'¿Cómo sé si un número es par o impar?',respuesta:'Un número es PAR si termina en 0, 2, 4, 6 u 8. Ejemplos: 12, 24, 36, 48. Un número es IMPAR si termina en 1, 3, 5, 7 o 9. Ejemplos: 13, 25, 37, 49. Los pares se dividen en dos grupos iguales; en los impares siempre sobra uno.',palabras_clave:['par','impar','número','termina','0','2','4','6','8','1','3','5','7','9','dividir']},
    {id:'mat_g3_075',grado:3,tema:'valor posicional',pregunta:'¿Qué es el valor posicional de un número?',respuesta:'El valor posicional dice cuánto vale cada dígito según su posición. En el número 547: el 5 está en las centenas (vale 500), el 4 está en las decenas (vale 40) y el 7 está en las unidades (vale 7). Entonces 547 = 500 + 40 + 7. Esto se llama forma expandida.',palabras_clave:['valor posicional','unidades','decenas','centenas','dígito','posición','cifra','forma expandida']},
    {id:'mat_g3_076',grado:3,tema:'medida con regla',pregunta:'¿Cómo mido un objeto con una regla?',respuesta:'Para medir con regla: coloca el cero de la regla al inicio del objeto, mantén la regla recta y lee el número donde termina el objeto. La unidad es el centímetro (cm). Ejemplo: si un lápiz va del 0 al 15, mide 15 cm. Recuerda: 10 mm = 1 cm y 100 cm = 1 metro.',palabras_clave:['medir','regla','centímetro','cm','milímetro','mm','metro','longitud','tamaño']},
    {id:'mat_g3_077',grado:3,tema:'fracciones propias',pregunta:'¿Qué es una fracción propia?',respuesta:'Una fracción propia es cuando el numerador (número de arriba) es MENOR que el denominador (número de abajo). Ejemplos: 1/4, 2/3, 3/8. Siempre representan menos que un entero. Si partes una naranja en 4 pedazos y te comes 1, comiste 1/4 de la naranja.',palabras_clave:['fracción propia','numerador','denominador','menor','entero','parte','1/4','2/3','3/8']},
    {id:'mat_g3_078',grado:3,tema:'comparar fracciones',pregunta:'¿Cómo comparo dos fracciones con el mismo denominador?',respuesta:'Cuando dos fracciones tienen el mismo denominador, el mayor es el que tiene el numerador más grande. Ejemplo: 3/8 > 2/8 porque 3 > 2. Si el denominador es diferente, convierte al mismo denominador primero. Ejemplo: 1/2 = 4/8, entonces 1/2 > 3/8.',palabras_clave:['comparar','fracciones','denominador','numerador','mayor','menor','igual']},
    {id:'mat_g3_079',grado:3,tema:'gráfica circular',pregunta:'¿Cómo leo una gráfica circular?',respuesta:'Una gráfica circular (o de torta) muestra partes de un todo divididas como sectores de un círculo. Cada color representa una categoría. Si la gráfica muestra que el 50% son niñas y 50% niños, cada mitad del círculo representa un grupo. Todos los sectores siempre suman 100%.',palabras_clave:['gráfica circular','torta','sector','porcentaje','categoría','datos','100%','mitad']},
    {id:'mat_g3_080',grado:3,tema:'problemas de dos pasos',pregunta:'¿Cómo resuelvo un problema que tiene dos operaciones?',respuesta:'Un problema de dos pasos requiere hacer dos operaciones en orden. Lee con atención e identifica qué pide. Ejemplo: Ana tiene 15 caramelos, le dan 8 más y luego regala 6. ¿Cuántos le quedan? Paso 1: 15+8=23. Paso 2: 23-6=17. Le quedan 17 caramelos.',palabras_clave:['problema','dos pasos','operaciones','paso a paso','razonar','leer','solución']},
    {id:'mat_g3_081',grado:3,tema:'tabla del 5',pregunta:'¿Cómo aprendo la tabla del 5?',respuesta:'La tabla del 5 siempre termina en 0 o 5: 5x1=5, 5x2=10, 5x3=15, 5x4=20, 5x5=25, 5x6=30, 5x7=35, 5x8=40, 5x9=45, 5x10=50. Truco: cuenta de 5 en 5. Es tan fácil que si cuentas las manos de todos tus compañeros, usas la tabla del 5.',palabras_clave:['tabla del 5','multiplicar','5','10','15','20','25','30','35','40','45','50']},
    {id:'mat_g3_082',grado:3,tema:'perímetro básico',pregunta:'¿Cómo calculo el perímetro de un rectángulo?',respuesta:'El perímetro es la suma de todos los lados de una figura. En un rectángulo: P = 2 x largo + 2 x ancho. Ejemplo: rectángulo de 6 cm de largo y 4 cm de ancho → P = 2x6 + 2x4 = 12 + 8 = 20 cm. Para el cuadrado: P = 4 x lado.',palabras_clave:['perímetro','rectángulo','lado','largo','ancho','suma','contorno','cuadrado']},

    // GRADO 4
    {id:'mat_g4_067',grado:4,tema:'números primos',pregunta:'¿Qué es un número primo?',respuesta:'Un número primo solo se puede dividir exactamente entre 1 y entre sí mismo. Ejemplos: 2, 3, 5, 7, 11, 13, 17, 19, 23. El número 1 NO es primo. El 4 no es primo porque 4÷2=2. Truco: intenta dividir entre 2, 3, 5... Si ninguno da exacto, es primo.',palabras_clave:['número primo','divisible','divisor','1','2','3','5','7','11','13','17']},
    {id:'mat_g4_068',grado:4,tema:'ángulos tipos',pregunta:'¿Qué diferencia hay entre ángulo agudo, recto y obtuso?',respuesta:'Un ángulo RECTO mide exactamente 90° (como la esquina de un cuaderno). Un ángulo AGUDO mide menos de 90° (como la punta de un triángulo equilátero). Un ángulo OBTUSO mide más de 90° pero menos de 180° (como una puerta entreabierta). El ángulo LLANO mide 180°.',palabras_clave:['ángulo','agudo','recto','obtuso','llano','90','180','grado','esquina']},
    {id:'mat_g4_069',grado:4,tema:'fracciones equivalentes avanzado',pregunta:'¿Cómo sé si dos fracciones son equivalentes?',respuesta:'Dos fracciones son equivalentes si representan la misma parte. Método 1: multiplica en cruz y compara. Ejemplo: 2/3 y 4/6 → 2x6=12 y 3x4=12, son iguales. Método 2: simplifica ambas a su forma irreducible. 4/6 ÷ 2 = 2/3. Son equivalentes.',palabras_clave:['equivalentes','fracciones','multiplicación cruzada','simplificar','irreducible','igual']},
    {id:'mat_g4_070',grado:4,tema:'propiedad asociativa',pregunta:'¿Qué es la propiedad asociativa?',respuesta:'La propiedad asociativa dice que puedes agrupar los números de diferente forma y el resultado es el mismo. Suma: (2+3)+4 = 2+(3+4) → 9 = 9. Multiplicación: (2x3)x4 = 2x(3x4) → 24 = 24. Esto te permite escoger el orden que más te convenga para calcular más rápido.',palabras_clave:['asociativa','propiedad','suma','multiplicación','agrupar','paréntesis','orden']},
    {id:'mat_g4_071',grado:4,tema:'área del triángulo',pregunta:'¿Cómo calculo el área de un triángulo?',respuesta:'El área de un triángulo se calcula con: Área = (base × altura) ÷ 2. La base es el lado inferior y la altura es la línea perpendicular hasta el vértice opuesto. Ejemplo: base=8 cm, altura=5 cm → Área = (8x5)÷2 = 40÷2 = 20 cm². La unidad de área siempre es cuadrada.',palabras_clave:['área','triángulo','base','altura','fórmula','dividir','2','cm cuadrado','perpendicular']},
    {id:'mat_g4_072',grado:4,tema:'porcentajes básicos',pregunta:'¿Qué es un porcentaje y cómo calculo el 50%, 25% y 10%?',respuesta:'Un porcentaje es una parte de cada 100 (símbolo %). El 50% = mitad (divide entre 2). El 25% = un cuarto (divide entre 4). El 10% = divide entre 10. Ejemplo: 50% de 80 = 40. 25% de 80 = 20. 10% de 80 = 8. Truco: 30% = 3 × 10%.',palabras_clave:['porcentaje','%','50','25','10','100','mitad','cuarto','calcular','dividir']},
    {id:'mat_g4_073',grado:4,tema:'múltiplos y divisores',pregunta:'¿Cuál es la diferencia entre múltiplos y divisores?',respuesta:'Los MÚLTIPLOS de un número son los resultados de multiplicarlo: múltiplos de 4 son 4,8,12,16,20... Los DIVISORES son los números que lo dividen exactamente: divisores de 12 son 1,2,3,4,6,12 (todos dividen 12 sin residuo). Los divisores son menores o iguales al número.',palabras_clave:['múltiplo','divisor','multiplicar','dividir','exacto','residuo','número']},
    {id:'mat_g4_074',grado:4,tema:'división de tres cifras',pregunta:'¿Cómo divido un número de tres cifras entre uno de una cifra?',respuesta:'Ejemplo: 648 ÷ 3. Paso 1: divide la primera cifra: 6÷3=2. Paso 2: baja el 4 → 04÷3=1 (resto 1). Paso 3: baja el 8 → 18÷3=6. Resultado: 216. Verificación: 216×3=648. Si la primera cifra es menor que el divisor, toma las dos primeras cifras juntas.',palabras_clave:['dividir','tres cifras','cociente','residuo','verificación','paso a paso','cifra']},
    {id:'mat_g4_075',grado:4,tema:'probabilidad simple',pregunta:'¿Qué es la probabilidad y cómo se calcula?',respuesta:'La probabilidad mide qué tan probable es un evento. Se calcula: probabilidad = casos favorables ÷ casos totales. Ejemplo: un dado tiene 6 caras. Probabilidad de sacar 3 = 1/6. Probabilidad de sacar número par (2,4,6) = 3/6 = 1/2. Va de 0 (imposible) a 1 (seguro).',palabras_clave:['probabilidad','evento','posible','fracción','dado','favorable','total','seguro','imposible']},
    {id:'mat_g4_076',grado:4,tema:'ecuaciones sencillas',pregunta:'¿Cómo resuelvo una ecuación simple con una incógnita?',respuesta:'Una ecuación tiene una incógnita (letra) que debes encontrar. Regla: lo que haces a un lado, lo haces al otro. Ejemplo 1: x + 5 = 12 → x = 12 - 5 = 7. Ejemplo 2: 3x = 18 → x = 18÷3 = 6. Siempre verifica: sustituye x y comprueba que la igualdad se cumple.',palabras_clave:['ecuación','incógnita','x','despejar','resolver','verificar','igual','lado']},

    // GRADO 5
    {id:'mat_g5_071',grado:5,tema:'operaciones con enteros',pregunta:'¿Cómo sumo y resto números enteros negativos?',respuesta:'Reglas para sumar enteros: mismo signo → suma los valores y conserva el signo. Diferente signo → resta el menor del mayor y usa el signo del número mayor en valor absoluto. Ejemplos: (-5)+(-3)=-8. (-5)+3=-(5-3)=-2. (+4)+(-7)=-(7-4)=-3.',palabras_clave:['negativo','entero','suma','resta','signo','recta numérica','positivo','valor absoluto']},
    {id:'mat_g5_072',grado:5,tema:'MCD',pregunta:'¿Qué es el MCD y cómo lo calculo?',respuesta:'El Máximo Común Divisor (MCD) es el número más grande que divide exactamente a dos o más números. Método: descompón en factores primos y toma los comunes con el menor exponente. Ejemplo: MCD(12,18) → 12=2²×3, 18=2×3² → MCD=2×3=6. Sirve para simplificar fracciones.',palabras_clave:['MCD','máximo común divisor','factor primo','descomponer','común','simplificar','exponente']},
    {id:'mat_g5_073',grado:5,tema:'multiplicación de fracciones',pregunta:'¿Cómo multiplico dos fracciones?',respuesta:'Para multiplicar fracciones: multiplica numerador con numerador y denominador con denominador. Ejemplo: 2/3 × 3/4 = (2×3)/(3×4) = 6/12 = 1/2. No necesitas igual denominador. Truco: antes de multiplicar, simplifica en forma cruzada para obtener números más pequeños.',palabras_clave:['multiplicar','fracciones','numerador','denominador','simplificar','cruzado','resultado']},
    {id:'mat_g5_074',grado:5,tema:'expresiones algebraicas',pregunta:'¿Qué es una expresión algebraica y cómo la evalúo?',respuesta:'Una expresión algebraica combina números, variables (letras) y operaciones. Ejemplo: 3x+5. Si x=2 entonces 3(2)+5=11. Para evaluar, sustituye la variable por el valor dado. Términos semejantes (misma variable) sí se suman: 2x+3x=5x. Distintos no: 2x+3y queda igual.',palabras_clave:['expresión algebraica','variable','término','coeficiente','semejante','evaluar','sustituir']},
    {id:'mat_g5_075',grado:5,tema:'media aritmética',pregunta:'¿Cómo calculo la media aritmética (promedio)?',respuesta:'La media aritmética se calcula sumando todos los valores y dividiendo entre cuántos hay. Ejemplo: notas de 5 estudiantes: 8,7,9,6,10 → suma=40 → media=40÷5=8. El promedio representa el valor central típico del conjunto. Se usa en calificaciones, temperaturas y estadísticas.',palabras_clave:['media','promedio','aritmética','sumar','dividir','datos','valor','calificaciones','estadística']},
    {id:'mat_g5_076',grado:5,tema:'volumen de prismas',pregunta:'¿Cómo calculo el volumen de un cubo y un prisma rectangular?',respuesta:'El volumen mide el espacio interior. Cubo: V = lado³. Ejemplo: lado=4 cm → V=4×4×4=64 cm³. Prisma rectangular: V = largo × ancho × alto. Ejemplo: 5×3×2=30 cm³. El volumen se mide en unidades cúbicas (cm³, m³). Una caja de leche de 1 litro tiene 1000 cm³.',palabras_clave:['volumen','cubo','prisma','largo','ancho','alto','cm cúbico','espacio','litro']},
    {id:'mat_g5_077',grado:5,tema:'regla de tres directa',pregunta:'¿Cómo resuelvo una regla de tres simple directa?',respuesta:'La regla de tres directa resuelve proporciones: si una cantidad aumenta, la otra también. Formato: A → B y C → X. Fórmula: X = (B × C) ÷ A. Ejemplo: si 3 cuadernos cuestan $9.000, ¿cuánto cuestan 5 cuadernos? X = (9000×5)÷3 = 45000÷3 = $15.000.',palabras_clave:['regla de tres','proporción','directa','precio','cantidad','calcular','cuadernos']},
    {id:'mat_g5_078',grado:5,tema:'números irracionales',pregunta:'¿Qué son los números irracionales?',respuesta:'Los números irracionales no se pueden escribir como fracción exacta y sus decimales son infinitos sin patrón que se repita. El más famoso es π (pi) ≈ 3.14159... y la raíz de 2 (√2) ≈ 1.41421... Se usan en geometría para calcular circunferencias y diagonales.',palabras_clave:['irracional','pi','raíz cuadrada','decimal','infinito','fracción','pi 3.14','√2']},
    {id:'mat_g5_079',grado:5,tema:'plano cartesiano avanzado',pregunta:'¿Cómo grafico una función sencilla en el plano cartesiano?',respuesta:'Para graficar y=2x: crea una tabla: si x=0, y=0; x=1, y=2; x=2, y=4; x=-1, y=-2. Ubica cada par ordenado (x,y) en el plano y únelos con una línea. Esa línea recta es la gráfica de la función. El eje horizontal es X y el vertical es Y.',palabras_clave:['plano cartesiano','función','graficar','tabla de valores','par ordenado','eje x','eje y','recta']},
    {id:'mat_g5_080',grado:5,tema:'teorema de Pitágoras',pregunta:'¿Qué es el teorema de Pitágoras y cómo lo aplico?',respuesta:'En un triángulo rectángulo: hipotenusa² = cateto1² + cateto2². La hipotenusa es el lado más largo (frente al ángulo recto). Ejemplo clásico: catetos 3 y 4 → hipotenusa² = 9+16 = 25 → hipotenusa = √25 = 5 cm. Se usa para medir distancias sin medir directamente.',palabras_clave:['Pitágoras','triángulo rectángulo','hipotenusa','cateto','cuadrado','raíz','3-4-5','distancia']}
  ];
  data.contenido.push(...nuevas);
  fs.writeFileSync(path, JSON.stringify(data, null, 2), 'utf8');
  console.log('matematicas.json OK. Total:', data.contenido.length);
}

// ─── ESPAÑOL ─────────────────────────────────────────────────────────────────
{
  const path = 'rag_api/knowledge_base/espanol.json';
  const data = JSON.parse(fs.readFileSync(path, 'utf8'));
  const nuevas = [
    // GRADO 3
    {id:'esp_g3_037',grado:3,tema:'uso del acento',pregunta:'¿Qué es el acento ortográfico (tilde) y cuándo se usa?',respuesta:'El acento ortográfico o tilde es una rayita (´) que se coloca sobre una vocal para indicar que esa sílaba se pronuncia más fuerte. Palabras agudas llevan tilde si terminan en n, s o vocal (corazón, café). Graves llevan tilde si NO terminan en n, s o vocal (árbol, lápiz). Esdrújulas siempre llevan tilde (pájaro, médico).',palabras_clave:['acento','tilde','ortografía','aguda','grave','esdrújula','sílaba','vocal','pronunciar']},
    {id:'esp_g3_038',grado:3,tema:'sustantivos tipos',pregunta:'¿Cuáles son los tipos de sustantivos?',respuesta:'Los sustantivos son palabras que nombran personas, animales, lugares o cosas. Tipos: PROPIOS nombran algo específico y se escriben con mayúscula (Colombia, Juan, Medellín). COMUNES nombran en general (ciudad, niño, perro). CONCRETOS se pueden tocar (mesa, pelota). ABSTRACTOS no se tocan (amor, libertad, miedo).',palabras_clave:['sustantivo','propio','común','concreto','abstracto','mayúscula','nombrar','persona','lugar']},
    {id:'esp_g3_039',grado:3,tema:'adjetivos',pregunta:'¿Qué es un adjetivo calificativo y cómo lo uso?',respuesta:'El adjetivo calificativo es la palabra que describe o da características al sustantivo. Ejemplos: pelota ROJA, niño INTELIGENTE, casa GRANDE. El adjetivo concuerda en género y número con el sustantivo: un perro NEGRO / una perra NEGRA / unos perros NEGROS. Siempre acompaña al sustantivo.',palabras_clave:['adjetivo','calificativo','describir','característica','género','número','concordancia','sustantivo']},
    {id:'esp_g3_040',grado:3,tema:'verbos tiempos',pregunta:'¿Cómo identifico si un verbo está en pasado, presente o futuro?',respuesta:'Los verbos cambian según el tiempo. PASADO: la acción ya ocurrió (comí, jugué, estudié). PRESENTE: la acción ocurre ahora (como, juego, estudio). FUTURO: la acción va a ocurrir (comeré, jugaré, estudiaré). Truco: pregúntate cuándo pasa la acción: ¿antes, ahora o después?',palabras_clave:['verbo','pasado','presente','futuro','tiempo','acción','conjugar','antes','ahora','después']},
    {id:'esp_g3_041',grado:3,tema:'el cuento',pregunta:'¿Cuáles son las partes de un cuento?',respuesta:'Un cuento tiene tres partes: INICIO (presentación de los personajes y el lugar donde ocurre la historia), NUDO (el problema o conflicto que viven los personajes, la parte más emocionante) y DESENLACE (la solución del problema y el final de la historia). Todo cuento tiene personajes principales y secundarios.',palabras_clave:['cuento','inicio','nudo','desenlace','personaje','problema','solución','historia','narrativo']},
    {id:'esp_g3_042',grado:3,tema:'texto descriptivo',pregunta:'¿Qué es un texto descriptivo y cómo se escribe?',respuesta:'Un texto descriptivo explica cómo es algo: su forma, color, tamaño, textura, olor. Se usa para describir personas, animales, lugares u objetos. Usa muchos adjetivos. Ejemplo: "El gato es pequeño, de pelo negro y brillante, con ojos verdes y una cola larga y esponjosa." Responde a la pregunta: ¿Cómo es?',palabras_clave:['descriptivo','describir','adjetivo','forma','color','tamaño','textura','características','texto']},
    {id:'esp_g3_043',grado:3,tema:'signos de puntuación',pregunta:'¿Para qué sirven el punto, la coma y los signos de interrogación?',respuesta:'El PUNTO (.) indica el final de una oración. La COMA (,) separa elementos de una lista o hace una pausa corta. Los signos de INTERROGACIÓN (¿?) van al inicio y al final de una pregunta. Los de EXCLAMACIÓN (¡!) expresan emoción o sorpresa. Usarlos bien hace el texto más claro.',palabras_clave:['punto','coma','interrogación','exclamación','signo de puntuación','oración','pausa','pregunta']},
    {id:'esp_g3_044',grado:3,tema:'sinónimos grado 3',pregunta:'¿Qué son los sinónimos y para qué los uso?',respuesta:'Los sinónimos son palabras que tienen un significado igual o muy parecido. Ejemplos: bonito/hermoso/lindo, rápido/veloz/ágil, triste/melancólico/afligido. Se usan para no repetir la misma palabra en un texto y hacer la escritura más variada e interesante. Es buena práctica buscarlos en el diccionario.',palabras_clave:['sinónimo','significado','igual','parecido','vocabulario','diccionario','variedad','repetir']},
    {id:'esp_g3_045',grado:3,tema:'párrafo',pregunta:'¿Qué es un párrafo y cómo lo escribo bien?',respuesta:'Un párrafo es un conjunto de oraciones relacionadas que desarrollan una misma idea. Comienza con sangría (espacio al inicio) o línea en blanco. Tiene: oración principal (la idea más importante) y oraciones de apoyo (explican o dan ejemplos). Un párrafo tiene mínimo 3 oraciones y habla de un solo tema.',palabras_clave:['párrafo','oración','idea','sangría','principal','apoyo','tema','escribir']},
    {id:'esp_g3_046',grado:3,tema:'diálogo',pregunta:'¿Cómo se escribe un diálogo en un cuento?',respuesta:'El diálogo es la conversación entre personajes. Se escribe con guion largo (—) al inicio de cada intervención. Ejemplo: — ¿A dónde vas? — preguntó Juan. — Voy al parque — respondió María. Las palabras del narrador (dijo, preguntó, respondió) van separadas del diálogo. Los signos de puntuación van dentro.',palabras_clave:['diálogo','guion','conversación','personaje','narrador','dijo','preguntó','respondió']},

    // GRADO 4
    {id:'esp_g4_028',grado:4,tema:'conectores textuales',pregunta:'¿Qué son los conectores textuales y cuáles son los más usados?',respuesta:'Los conectores son palabras o frases que unen oraciones y párrafos para que el texto fluya con sentido. De adición: además, también, igualmente. De contraste: pero, sin embargo, aunque. De causa: porque, ya que, debido a. De consecuencia: por lo tanto, entonces, así que. De secuencia: primero, luego, finalmente.',palabras_clave:['conector','textual','además','pero','porque','sin embargo','por lo tanto','primero','luego','finalmente']},
    {id:'esp_g4_029',grado:4,tema:'la noticia',pregunta:'¿Qué es una noticia y qué partes tiene?',respuesta:'La noticia informa sobre un hecho real y reciente. Sus partes son: TITULAR (título llamativo que resume el evento), SUBTÍTULO (complementa el titular), ENTRADILLA (primer párrafo con lo más importante: qué, quién, cuándo, dónde, por qué y cómo) y CUERPO (detalles y contexto del hecho). Debe ser objetiva y veraz.',palabras_clave:['noticia','titular','subtítulo','entradilla','cuerpo','hecho','real','informar','periodismo']},
    {id:'esp_g4_030',grado:4,tema:'carta formal e informal',pregunta:'¿Qué diferencia hay entre una carta formal y una informal?',respuesta:'La carta FORMAL se escribe a una institución, empresa o persona desconocida. Usa lenguaje respetuoso y estructura fija: encabezado, saludo formal (Estimado señor/a), cuerpo, despedida (Atentamente) y firma. La INFORMAL es para amigos o familia: lenguaje cercano, saludo afectuoso (Querido amigo) y despedida cariñosa.',palabras_clave:['carta','formal','informal','encabezado','saludo','despedida','lenguaje','respetuoso','amigo']},
    {id:'esp_g4_031',grado:4,tema:'discurso directo e indirecto',pregunta:'¿Cuál es la diferencia entre el discurso directo e indirecto?',respuesta:'El DISCURSO DIRECTO reproduce exactamente las palabras del hablante con comillas o guion: Juan dijo: "Tengo hambre." El DISCURSO INDIRECTO las reporta sin comillas, cambiando pronombres y tiempos verbales: Juan dijo que tenía hambre. El indirecto integra las palabras al relato del narrador.',palabras_clave:['discurso directo','discurso indirecto','comillas','guion','narrador','verbos','reportar','citar']},
    {id:'esp_g4_032',grado:4,tema:'texto argumentativo',pregunta:'¿Qué es un texto argumentativo y cómo se estructura?',respuesta:'El texto argumentativo busca convencer al lector de una postura. Estructura: TESIS (idea principal que se defiende), ARGUMENTOS (razones, datos y ejemplos que apoyan la tesis) y CONCLUSIÓN (reafirma la tesis). Ejemplo: Tesis: el deporte es esencial. Argumento: mejora la salud y la concentración.',palabras_clave:['argumentativo','tesis','argumento','conclusión','convencer','opinar','razón','evidencia','postura']},
    {id:'esp_g4_033',grado:4,tema:'prefijos y sufijos',pregunta:'¿Qué son los prefijos y sufijos en español?',respuesta:'Los PREFIJOS van al inicio de una palabra y cambian su significado: in- (imposible), des- (desorden), re- (rehacer), pre- (prehistoria). Los SUFIJOS van al final y cambian el significado o la categoría: -ción (canción), -mente (rápidamente), -ito (gatito, diminutivo), -ísimo (grandísimo, superlativo).',palabras_clave:['prefijo','sufijo','morfema','in','des','re','ción','mente','ito','significado','familia de palabras']},
    {id:'esp_g4_034',grado:4,tema:'oración sujeto predicado',pregunta:'¿Cómo identifico el sujeto y el predicado de una oración?',respuesta:'El SUJETO es quien realiza la acción o de quien se habla. El PREDICADO es lo que se dice del sujeto (incluye el verbo). Ejemplo: "Los estudiantes de grado 4 estudian mucho." Sujeto: Los estudiantes de grado 4. Predicado: estudian mucho. Truco: pregunta ¿quién? o ¿qué? hace la acción para encontrar el sujeto.',palabras_clave:['oración','sujeto','predicado','verbo','acción','quién','identificar','análisis']},
    {id:'esp_g4_035',grado:4,tema:'resumen',pregunta:'¿Cómo hago un buen resumen de un texto?',respuesta:'Para resumir: 1) Lee el texto completo. 2) Identifica las ideas principales (una por párrafo). 3) Elimina ejemplos, repeticiones y detalles secundarios. 4) Escribe las ideas principales con tus propias palabras. 5) Organiza en párrafos coherentes. Un resumen debe ser más corto que el texto original pero mantener su significado.',palabras_clave:['resumen','ideas principales','párrafo','texto','síntesis','releer','organizar','comprensión']},
    {id:'esp_g4_036',grado:4,tema:'mapa conceptual',pregunta:'¿Cómo elaboro un mapa conceptual?',respuesta:'Un mapa conceptual organiza ideas visualmente. Pasos: 1) Escribe el tema central en un óvalo. 2) Anota las ideas principales relacionadas y únelas con líneas. 3) Agrega ideas secundarias a cada principal. 4) Usa palabras de enlace en las líneas (es, tiene, produce, incluye). Ayuda a estudiar y comprender mejor los textos.',palabras_clave:['mapa conceptual','organizar','ideas','óvalo','enlace','visual','esquema','jerarquía']},
    {id:'esp_g4_037',grado:4,tema:'lectura inferencial',pregunta:'¿Qué es una inferencia en la lectura?',respuesta:'Una inferencia es una conclusión que sacas de lo que el texto dice sin decirlo directamente. Ejemplo: si un texto dice "María entró empapada y dejando charcos", puedes inferir que llovía aunque no lo diga. Para inferir: lee entre líneas, relaciona datos y usa tu conocimiento previo. Es la lectura más profunda.',palabras_clave:['inferencia','concluir','leer entre líneas','implícito','texto','comprender','significado','deducir']},

    // GRADO 5
    {id:'esp_g5_028',grado:5,tema:'figuras literarias',pregunta:'¿Qué son las figuras literarias y cuáles son las principales?',respuesta:'Las figuras literarias son recursos del lenguaje que dan belleza y expresividad al texto. Principales: METÁFORA: comparar sin usar "como" (tus ojos son estrellas). SÍMIL: comparar usando "como" (rápido como el viento). PERSONIFICACIÓN: dar cualidades humanas a cosas (el mar llora). HIPÉRBOLE: exageración (te lo he dicho un millón de veces).',palabras_clave:['figura literaria','metáfora','símil','personificación','hipérbole','lenguaje','poético','expresividad']},
    {id:'esp_g5_029',grado:5,tema:'el ensayo',pregunta:'¿Qué es un ensayo y cómo se diferencia del texto argumentativo?',respuesta:'El ensayo es un texto donde el autor expresa sus ideas y reflexiones sobre un tema de forma personal y fundamentada. A diferencia del texto argumentativo puro, el ensayo tiene mayor libertad estilística y puede mezclar argumentación, análisis y opinión. Partes: introducción, desarrollo argumentado y conclusión reflexiva.',palabras_clave:['ensayo','opinión','reflexión','argumentar','personal','introducción','desarrollo','conclusión']},
    {id:'esp_g5_030',grado:5,tema:'el debate',pregunta:'¿Cómo participo en un debate escolar?',respuesta:'En un debate defienden posturas distintas sobre un tema. Para participar bien: 1) Prepara argumentos con datos y ejemplos. 2) Escucha con respeto al otro. 3) Responde con contraargumentos lógicos, no con insultos. 4) Usa conectores de contraste (sin embargo, aunque, por el contrario). 5) Concluye con una síntesis de tu postura.',palabras_clave:['debate','argumento','contraargumento','postura','respeto','escuchar','defender','opinar','lógica']},
    {id:'esp_g5_031',grado:5,tema:'la entrevista',pregunta:'¿Qué es una entrevista y cómo se estructura?',respuesta:'La entrevista es un diálogo con el propósito de obtener información de una persona experta o reconocida. Partes: PRESENTACIÓN del entrevistado, PREGUNTAS del entrevistador (abiertas para respuestas amplias) y RESPUESTAS del entrevistado. Las preguntas buenas comienzan con ¿Por qué?, ¿Cómo?, ¿Qué piensa sobre...?',palabras_clave:['entrevista','entrevistado','entrevistador','pregunta','respuesta','diálogo','información','periodismo']},
    {id:'esp_g5_032',grado:5,tema:'reseña literaria',pregunta:'¿Cómo escribo una reseña de un libro?',respuesta:'Una reseña evalúa y recomienda (o no) un libro. Partes: 1) Datos del libro (título, autor, año). 2) Breve resumen del argumento SIN revelar el final. 3) Análisis de personajes, tema y estilo del autor. 4) Opinión personal fundamentada: ¿Qué te gustó? ¿Qué no? 5) Recomendación. No es solo un resumen, es una evaluación.',palabras_clave:['reseña','libro','autor','argumento','personaje','tema','opinión','recomendar','evaluar']},
    {id:'esp_g5_033',grado:5,tema:'coherencia y cohesión',pregunta:'¿Qué es la coherencia y la cohesión en un texto?',respuesta:'La COHERENCIA hace que el texto tenga sentido y las ideas se relacionen lógicamente (no mezcla temas sin conexión). La COHESIÓN es cómo las oraciones están bien conectadas gramaticalmente (uso de conectores, pronombres y sinónimos para no repetir palabras). Un texto bueno tiene ambas. Coherencia = ideas. Cohesión = forma.',palabras_clave:['coherencia','cohesión','texto','lógica','conector','pronombre','sinónimo','sentido','organización']},
    {id:'esp_g5_034',grado:5,tema:'textos multimodales',pregunta:'¿Qué son los textos multimodales?',respuesta:'Los textos multimodales combinan diferentes modos de comunicación: palabras escritas, imágenes, gráficas, videos, audio o íconos. Ejemplos: una infografía, un afiche publicitario, una página web, un cómic. Para leerlos hay que interpretar tanto el texto escrito como las imágenes y cómo se relacionan entre sí.',palabras_clave:['multimodal','imagen','texto','infografía','afiche','cómic','video','icono','leer','interpretar']},
    {id:'esp_g5_035',grado:5,tema:'comunicación digital',pregunta:'¿Cómo debo comunicarme de forma responsable en medios digitales?',respuesta:'La comunicación digital responsable implica: 1) Verificar la información antes de compartirla (evitar fake news). 2) Usar lenguaje respetuoso en chats y redes. 3) Cuidar la privacidad (no compartir datos personales). 4) Reconocer el ciberacoso y reportarlo. 5) Diferenciar entre fuentes confiables y no confiables.',palabras_clave:['digital','comunicación','responsable','fake news','privacidad','ciberacoso','redes','verificar','fuente']}
  ];
  data.contenido.push(...nuevas);
  fs.writeFileSync(path, JSON.stringify(data, null, 2), 'utf8');
  console.log('espanol.json OK. Total:', data.contenido.length);
}

